<?php require __DIR__.'/../config/config.php';require_admin();if(isset($_POST['delete'])){db()->prepare('DELETE FROM profiles WHERE id=?')->execute([(int)$_POST['delete']]);}if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['save'])){$data=[$_POST['gender'],$_POST['name'],(int)$_POST['age'],$_POST['state'],$_POST['city'],$_POST['about'],$_POST['marital_status'],$_POST['annual_income'],$_POST['description'],$_POST['caste'],$_POST['religion'],$_POST['whatsapp'],isset($_POST['active'])?1:0];if(!empty($_POST['id'])){db()->prepare('UPDATE profiles SET gender=?,name=?,age=?,state=?,city=?,about=?,marital_status=?,annual_income=?,description=?,caste=?,religion=?,whatsapp=?,active=? WHERE id=?')->execute([...$data,(int)$_POST['id']]);}else{db()->prepare('INSERT INTO profiles(gender,name,age,state,city,about,marital_status,annual_income,description,caste,religion,whatsapp,active) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute($data);}}$ps=db()->query('SELECT * FROM profiles ORDER BY gender,id')->fetchAll();?>
<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="../assets/style.css"></head><body><main class="phone"><header><a href="index.php">←</a><b>Profiles</b></header><section class="card"><h3>Add / Edit Profile</h3><form method="post"><input type="hidden" name="id" value=""><select name="gender"><option value="female">Female</option><option value="male">Male</option></select><input name="name" placeholder="Name"><input name="age" type="number" placeholder="Age"><input name="state" placeholder="State"><input name="city" placeholder="City"><textarea name="about" placeholder="About Me"></textarea><input name="marital_status" placeholder="Marital Status"><input name="annual_income" placeholder="Annual Income"><textarea name="description" placeholder="Description"></textarea><input name="caste" placeholder="Caste"><input name="religion" placeholder="Religion"><input name="whatsapp" placeholder="WhatsApp"><label><input type="checkbox" name="active" checked> Active</label><button name="save">Save Profile</button></form></section><section class="card"><h3>Existing Profiles</h3><?php foreach($ps as $p):?><div style="padding:10px 0;border-bottom:1px solid #eee"><b><?=h($p['name'])?></b> · <?=h($p['gender'])?> · <?=h($p['city'])?><form method="post"><button name="delete" value="<?=$p['id']?>" style="background:#444">Delete</button></form></div><?php endforeach;?></section></main><script src="/rishtewale-protection.js"></script>
</body></html>
